optimized_cypher:
// Workspace filter and hub‑defense indexed start node
MATCH (a:Account {_workspace_id: 'ws_test'})
USING INDEX a:Account(acct_no)
WHERE a.acct_no = 1001

// Follow outgoing TRANSFER relationships up to two hops
MATCH (a)-[:TRANSFER*1..2]->(b:Account {_workspace_id: 'ws_test'})

// Aggregate results
RETURN 
    count(DISTINCT b)        AS reachable_accounts,
    max(b.risk_tier)         AS max_risk_tier;

